// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(v > 0);
        vm.assume(_decimals <= 18);
        uint _value = v * 10 ** _decimals;
        // Record initial balances for all recipients
        uint[] memory initialBalances = new uint[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.call(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            if (success && data.length == 32) {
                initialBalances[i] = abi.decode(data, (uint));
            } else {
                initialBalances[i] = 0;
            }
        }
        // Call transfer
        bool result = c.transfer(from, caddress, _tos, v, _decimals);
        vm.assume(result == true);
        // After the call, every recipient must have its balance increased by exactly _value
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.call(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            uint newBalance = 0;
            if (success && data.length == 32) {
                newBalance = abi.decode(data, (uint));
            }
            assertTrue(newBalance == initialBalances[i] + _value, "All recipients must receive the transfer");
        }
    }
}

