interface IERC20 {
    function transferFrom(address, address, uint) external returns (bool);
    function getLastCaller() external view returns (address);
    function getCallCount() external view returns (uint);
}

contract TrackingToken is IERC20 {
    address public lastCaller;
    uint public callCount;
    function transferFrom(address from, address, uint) external returns (bool) {
        lastCaller = from;
        callCount++;
        return true;
    }
    function getLastCaller() external view returns (address) { return lastCaller; }
    function getCallCount() external view returns (uint) { return callCount; }
}

contract InvMutTest is Test {
    C c;
    TrackingToken token;
    function setUp() public {
        c = new C();
        token = new TrackingToken();
    }
    function testFuzz_property(address from, address[] memory _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        vm.assume(_decimals <= 18);
